using Nexora.Application.Customers;using Nexora.Application.Tenancy;
namespace Nexora.Api.Customers;
public static class CustomerEndpoints
{
 public static IEndpointRouteBuilder MapCustomerEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/v1/customers").WithTags("Customers");g.MapGet("/",(string? search,string? status,string? sort,int? page,int? pageSize,ITenantContext t,ICustomerService s,CancellationToken ct)=>s.SearchAsync(t.TenantId,search,status,sort??"name",page??1,pageSize??20,ct)).RequireAuthorization(TenantPermissions.CustomersRead);g.MapGet("/{id:guid}",async(Guid id,ITenantContext t,ICustomerService s,CancellationToken ct)=>await s.GetAsync(t.TenantId,id,ct)is{}x?Results.Ok(x):Results.NotFound()).RequireAuthorization(TenantPermissions.CustomersRead);g.MapPost("/",async(CustomerInput i,ITenantContext t,ICustomerService s,CancellationToken ct)=>Results.Created("/api/v1/customers",await s.CreateAsync(t.TenantId,i,ct))).RequireAuthorization(TenantPermissions.CustomersCreate);g.MapPut("/{id:guid}",async(Guid id,CustomerInput i,ITenantContext t,ICustomerService s,CancellationToken ct)=>await s.UpdateAsync(t.TenantId,id,i,ct)is{}x?Results.Ok(x):Results.NotFound()).RequireAuthorization(TenantPermissions.CustomersUpdate);g.MapDelete("/{id:guid}",async(Guid id,ITenantContext t,ICustomerService s,CancellationToken ct)=>await s.DeleteAsync(t.TenantId,id,ct)?Results.NoContent():Results.NotFound()).RequireAuthorization(TenantPermissions.CustomersDelete);return e;}
}
